date='2026-10-10T00:00:00.000Z';catalog=[];posts=[]
for slug,category,title,excerpt,seo_title,seo_description in rows:
 record=dict(id=str(uuid5(NAMESPACE_URL,'https://laplongesadapte.com/blog/'+slug+'/')),slug=slug,category=category,title=title,excerpt=excerpt,seo_title=seo_title,seo_description=seo_description,author_name='La Plonge s’Adapte',status='published',published_at=date,created_at=date,updated_at=date,cover_url='',cover_alt='')
 catalog.append(record);posts.append(dict(record,content_markdown=(ROOT/'src/content/blog'/f'{slug}.md').read_text().strip()))
(ROOT/'src/content/blog/catalog.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
seed=ROOT/'supabase/seeds';seed.mkdir(exist_ok=True)
payload=json.dumps(posts,ensure_ascii=False);assert '$lpsa_editorial$' not in payload
(seed/'initial-blog.sql').write_text('-- Initial editorial collection, 10 October 2026. Re-runnable: never overwrites an existing slug.\nBEGIN;\nINSERT INTO public.blog_posts SELECT * FROM jsonb_populate_recordset(NULL::public.blog_posts, $lpsa_editorial$'+payload+'$lpsa_editorial$::jsonb) ON CONFLICT (slug) DO NOTHING;\nCOMMIT;\n')
# Preserve previously edited demo articles; seed only missing slugs.
local=ROOT/'.local/posts.json';old=json.loads(local.read_text()) if local.exists() else [];known={p['slug'] for p in old};old.extend(p for p in posts if p['slug'] not in known);local.write_text(json.dumps(old,ensure_ascii=False))
for p in posts:print(p['slug'],len(p['content_markdown'].split()),'words')
